using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // Breaking change: EF Core 9 Cosmos provider blocks sync I/O by default.
        // Allow it so ToList() / SaveChanges() keep working.
        optionsBuilder.ConfigureWarnings(w =>
            w.Ignore(Microsoft.EntityFrameworkCore.Diagnostics.CosmosEventId.SyncNotSupported));
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change: HasIndex() now throws on Cosmos (was silently ignored).
        // Removed: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);

        // Breaking change: default discriminator property renamed from
        // "Discriminator" to "$type". Preserve the old name so existing
        // documents are still found by queries like:
        //   SELECT * FROM c WHERE c.Discriminator = 'Blog'
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change: id values no longer include the discriminator prefix.
        // Old format: "Blog|1", new format: "1".
        // Preserve the old id format so existing documents are still addressable.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .HasJsonPropertyName("id");
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

